```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *reverse_string(char *input) {
    // make sure the input is not null
    if (input == NULL) {
        return NULL;
    }

    // make sure the input is not empty
    if (strlen(input) == 0) {
        return input;
    }

    // create a new string to store the reversed string
    char *reversed = malloc(strlen(input) * sizeof(char));

    // reverse the string
    for (int i = 0; i < strlen(input); i++) {
        reversed[i] = input[strlen(input) - i - 1];
    }

    // return the reversed string
    return reversed;
}

int main(int argc, char *argv[]) {
    // make sure 1 argument was provided
    if (argc!= 2) {
        printf("Need 1 argument\n");
        exit(1);
    }

    // get the argument
    char *input = argv[1];

    // print the argument
    printf("'%s'\n", input);

    // reverse the string
    char *reversed = reverse_string(input);

    // print the reversed string
    printf("'%s'\n", reversed);

    // free the memory
    free(reversed);

    return 0;
}
