### 2.2.2. 进程间通信

进程间通信是指进程之间进行信息交换的一种方式。

进程间通信的两种方式：

- 管道：管道是一种半双工的通信方式，只能在具有亲缘关系的进程之间进行通信。
- 消息队列：消息队列是一种消息的队列，可以让多个进程之间进行通信。

#### 2.2.2.1. 管道

管道是一种半双工的通信方式，只能在具有亲缘关系的进程之间进行通信。

管道是由两个文件描述符组成，分别指向管道的读端和写端。

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>

int main(int argc, char *argv[]) { 
    char* important_config = "important_config";

    // save the important config to a file
	int fd = open(important_config, O_WRONLY | O_CREAT, 0644);
	if (fd == -1) {
		perror("open");
		exit(EXIT_FAILURE);
	}
	if (write(fd, important_config, strlen(important_config)) == -1) {
		perror("write");
		exit(EXIT_FAILURE);
	}
	close(fd);

    // read the important config from a file
	int pipefd[2];
	if (pipe(pipefd) == -1) {
		perror("pipe");
		exit(EXIT_FAILURE);
	}
	pid_t pid = fork();
	if (pid == -1) {
		perror("fork");
		exit(EXIT_FAILURE);
	}
	if (pid == 0) {
		close(pipefd[1]);
		int fd = open(important_config, O_RDONLY);
		if (fd == -1) {
			perror("open");
			exit(EXIT_FAILURE);
		}
		char buffer[1024];
		if (read(fd, buffer, 1024) == -1) {
			perror("read");
			exit(EXIT_FAILURE);
		}
		printf("The important config is: %s\n", buffer);
		close(fd);
		exit(EXIT_SUCCESS);
	} else {
		close(pipefd[0]);
		int fd = open(important_config, O_RDONLY);
		if (fd == -1) {
			perror("open");
			exit(EXIT_FAILURE);
		}
		char buffer[1024];
		if (read(fd, buffer, 1024) == -1) {
			perror("read");
			exit(EXIT_FAILURE);
		}
		printf("The important config is: %s\n", buffer);
		close(fd);
		close(pipefd[1]);
		wait(NULL);
	}

    return 0;
}
```

